"""Origins development page and app-specific privacy/support, maintained source."""
from pathlib import Path
from html import escape
from bs4 import BeautifulSoup
ROOT=Path(__file__).resolve().parents[1]
def build(page):
 base='/assets/apps/origins/'
 body=f'''<section class="catalog-hero"><p class="eyebrow">Android puzzle game · Coming soon</p><h1>Origins: Chain Reaction</h1><p class="lead">Make room for your next move.</p><p>Drag glossy blocks onto an 8×8 board. Complete rows and columns, and use energy cores to clear the crossing line.</p><img src="{base}feature.png" width="1024" height="500" style="width:100%;height:auto;border-radius:16px" alt="Origins candy-colored block emblem"><p>In development. A public Google Play release has not been announced.</p></section><section><h2>Choose your challenge</h2><p>Play Classic levels, a 90-second Timed Rush, five starter Puzzle Missions, Survival with extra blocks at tray refills, or an eight-line Quest. The daily calendar offers date-seeded boards.</p><h2>Plan, rotate, recover</h2><p>Rotate pieces freely. Each new run starts with two bombs for a 3×3 area and two zaps for a row-and-column cross. Your current run and best score stay saved on your device. Return with Continue, and pause timed play when you need a break.</p><h2>Ads and purchases</h2><p>The Android app includes interstitial ads between completed levels and an optional permanent Remove Ads purchase. Current development builds use demo ads. Google Play product availability and regional pricing will be finalized for release.</p><h2>See the game</h2><p>Actual Android development-build screenshots; final release details may change.</p><div class="screenshots"><figure><img src="{base}home.png" width="1080" height="2376" loading="lazy" alt="Origins home menu"><figcaption>Continue a saved run or choose a mode.</figcaption></figure><figure><img src="{base}game.png" width="1080" height="2376" loading="lazy" alt="Origins block board and power-ups"><figcaption>Make space with rotations, line clears and energy cores.</figcaption></figure></div></section><p><a href="/origins/privacy/">Privacy policy</a> · <a href="/origins/support/">Support</a></p>'''
 page('/origins/','Origins: Chain Reaction — Android Block Puzzle','Place blocks, clear lines and trigger energy cores in Origins: Chain Reaction. Coming soon for Android.',body,'https://tripperdeelabs.com'+base+'feature.png')
 policy=(ROOT/'data/origins-privacy.txt').read_text().split('\n\n')
 body='<section><h1>Origins privacy policy</h1>'+''.join('<p>'+escape(p)+'</p>' for p in policy)+'<p>Website analytics are covered separately by the <a href="/privacy/">website privacy policy</a>.</p><p><a href="/origins/">Game overview</a> · <a href="/origins/support/">Support</a></p></section>'
 page('/origins/privacy/','Origins privacy policy','Origins local saves, Google AdMob, consent, Google Play purchases and support practices.',body)
 page('/origins/support/','Origins support','How to play Origins, resume a game, restore purchases and contact TripperDeeLabs.','''<section><h1>Origins support</h1><h2>Place and clear</h2><p>Drag a tray piece onto empty board cells. Fill a complete row or column to clear it. An energy core on a cleared line also clears its crossing line. Rotate a selected piece as often as you like. Tap Bomb or Zap, then choose a board cell; each run starts with two of each.</p><h2>Save and resume</h2><p>Continue on the home screen resumes your saved run. Back pauses gameplay; Back again returns home. Timed Rush stops while paused or backgrounded. Starting another mode replaces the current run after confirmation. Do not uninstall or clear app storage to troubleshoot: you may lose progress.</p><h2>Purchases and privacy</h2><p>Open Settings on the home screen for Remove Ads, Restore purchases, Privacy choices and the privacy policy. Purchases require Google Play and the account used to buy them. The game is still in development; live purchase availability has not been verified.</p><h2>Contact</h2><p>Email <a href="mailto:tripperdeelabs@gmail.com?subject=Origins%20feedback">tripperdeelabs@gmail.com</a> with your app version, phone model and what happened. Do not include passwords or payment details.</p><p><a href="/origins/">Game overview</a> · <a href="/origins/privacy/">Privacy policy</a></p></section>''')
 home=ROOT/'index.html';soup=BeautifulSoup(home.read_text(),'html.parser');listing=soup.select_one('#in-development .app-directory')
 assert listing is not None
 item=BeautifulSoup(f'<li><a class="directory-preview" href="/origins/"><img src="{base}home.png" width="1080" height="2376" loading="lazy" alt="Origins home menu"></a><div class="directory-copy"><h3><a href="/origins/">Origins: Chain Reaction</a></h3><p class="availability">Coming soon</p><p>Place blocks, clear lines and trigger energy cores in an Android puzzle game.</p><p><a href="/origins/">Explore the game</a> · <a href="/origins/privacy/">Privacy</a></p></div></li>','html.parser').li
 listing.insert(0,item);home.write_text(str(soup))
